public static class NativeRpcBootstrapLauncherHarness {
 static int count;static void Check(bool x){if(!x)throw new Exception("Assertion");}static void Refuse(Action f){bool failed=false;try{f();}catch{failed=true;}Check(failed);}static void Test(string name,Action f){f();count++;Console.WriteLine("PASS "+name);}static string H(char c){return new string(c,64);}static byte[] B(string s){return Encoding.UTF8.GetBytes(s);}
 static Dictionary<string,object> D(params object[] x){var d=new Dictionary<string,object>();for(int i=0;i<x.Length;i+=2)d.Add((string)x[i],x[i+1]);return d;}
 sealed class Case:IDisposable {
  internal readonly string Root,Home,Workers,Config=H('a');internal readonly long Now=BoundedWorker.MonotonicMilliseconds();internal readonly byte[] Worker=B("inert pinned worker fixture"),Keeper=B("inert pinned keeper fixture");internal readonly NativeRpcManagerLedger Ledger;internal readonly NativeRpcDefinitionPlan Plan;internal readonly string Original;
  internal Case(){Home=Path.Combine(Path.GetPathRoot(Environment.SystemDirectory),"rpc-start-launch-"+Guid.NewGuid().ToString("N"));var acl=new DirectorySecurity();acl.SetOwner(new SecurityIdentifier("S-1-5-32-544"));acl.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.CreateDirectory(Home,acl);Root=Path.Combine(Home,"ledger");Directory.CreateDirectory(Root,acl);Workers=Path.Combine(Home,"workers");Directory.CreateDirectory(Workers,acl);
   var security=new FileSecurity();security.SetOwner(new SecurityIdentifier("S-1-5-32-544"));security.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})security.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,AccessControlType.Allow));using(var f=new FileStream(Path.Combine(Root,"manager.lock"),FileMode.CreateNew,FileSystemRights.WriteData,FileShare.None,4096,FileOptions.WriteThrough,security))f.Flush(true);
   Ledger=new NativeRpcManagerLedger(Root,Config,Current);Ledger.Files.NewDirectory(Path.Combine(Root,"transport"));var a=Ledger.Begin(new string('b',32),"rpc"+new string('c',32),"0x"+H('d'),Now);Original=ProtectedAttempt.Hash(NativeRpcManagerLedger.Encode(a));string attempt=(string)a["attempt"];
   Plan=new NativeRpcDefinitionPlan(attempt,(string)a["boot"],(string)a["managerEpoch"],(string)a["instance"],(string)a["deployment"],H('e'),H('f'),H('a'),H('b'),H('c'),H('d'),Path.Combine(Home,attempt),Now,Now+900000,H('e'),H('f'),ProtectedAttempt.Hash(Worker));
   Ledger.Files.NewDirectory(Plan.Root);Ledger.Files.Publish(Path.Combine(Plan.Root,"native-definition-plan.txt"),B(Plan.Encode()));
  }
  internal void Current(){if(BoundedWorker.MonotonicMilliseconds()-Now>=15000)throw new Exception("Fixture deadline");}
  internal Dictionary<string,object> Bootstrap(){
   var files=Ledger.Files;string assets=Path.Combine(Home,"assets");files.NewDirectory(assets);string source=Path.Combine(assets,"source");files.NewDirectory(source);
   foreach(string name in new[]{"worker","controller","node","tpm","key"})files.Publish(Path.Combine(assets,name),Worker);
   var names=new List<string>();foreach(string n in ProtectedAttempt.BootstrapSourceNames){string file=Path.Combine(source,n.Replace('/','\\')),dir=Path.GetDirectoryName(file);var parts=dir.Substring(source.Length+1).Split('\\');string path=source;foreach(string part in parts){path=Path.Combine(path,part);if(!Directory.Exists(path))files.NewDirectory(path);}files.Publish(file,B("inert source fixture"));names.Add(n+"|"+ProtectedAttempt.Hash(B("inert source fixture")));}
   byte[] manifest=B(String.Join("\n",names)+"\n");files.Publish(Path.Combine(source,"bootstrap-source.txt"),manifest);string hash=ProtectedAttempt.Hash(Worker);
   return D("schema","native-rpc-bootstrap-controller/1","managerConfigSha256",Config,"controllerPath",Path.Combine(assets,"controller"),"controllerSha256",hash,"workerPath",Path.Combine(assets,"worker"),"workerSha256",hash,"nodePath",Path.Combine(assets,"node"),"nodeSha256",hash,"tpmPath",Path.Combine(assets,"tpm"),"tpmSha256",hash,"keyPath",Path.Combine(assets,"key"),"keySha256",hash,"sourceRoot",source,"sourceSha256",ProtectedAttempt.Hash(manifest),"expectedBase64",Convert.ToBase64String(B("{}")),"ekChainBase64",Convert.ToBase64String(B("[]")));
  }
  internal NativeBootstrapContract Prepare(Dictionary<string,object> config,long end){return new NativeBootstrapContract(Ledger.Files,Plan,Workers,config,D("vmGuid","12345678-1234-1234-1234-123456789abc","ownedReceipt",H('e')),D("receipt",H('f')),end);}
  public void Dispose(){Ledger.Dispose();}
 }
 public static int Main(string[] args){try{if(args.Length!=0)throw new ArgumentException("No selection");BoundedWorker.EnterSupervisorEnvelope(256UL*1048576);
  Test("explicit bootstrap configuration binds original manager and fixed dependency pins",()=>{using(var c=new Case()){var d=c.Bootstrap();NativeBootstrapContract.Configuration(d,c.Config);Refuse(()=>NativeBootstrapContract.Configuration(d,H('b')));d["workerSha256"]=new string('0',64);Refuse(()=>NativeBootstrapContract.Configuration(d,c.Config));d["workerSha256"]=ProtectedAttempt.Hash(c.Worker);d.Add("command","arbitrary");Refuse(()=>NativeBootstrapContract.Configuration(d,c.Config));}});
  Test("consumed bootstrap subtree survives reconstruction and refuses repeat preparation",()=>{string root,hash;NativeRpcDefinitionPlan p;using(var c=new Case()){root=c.Root;hash=c.Original;p=c.Plan;NativeBootstrapContract.Consume(c.Ledger,c.Original,H('b'),p,B("start receipt"));Check(File.Exists(Path.Combine(root,"bootstrap","request.json")));Check(!File.Exists(Path.Combine(root,"bootstrap","dispatch.json")));Check((string)c.Ledger.Inspect()["state"]=="held");}using(var ledger=new NativeRpcManagerLedger(root,H('a'),()=>{})){ledger.Original(hash);Refuse(()=>NativeBootstrapContract.Consume(ledger,hash,H('b'),p,B("start receipt")));}});
  Test("prepared bootstrap pins original v2 plan under a closed bounded phase gate",()=>{using(var c=new Case()){var d=c.Bootstrap();NativeBootstrapContract.Configuration(d,c.Config);NativeBootstrapContract.Consume(c.Ledger,c.Original,H('b'),c.Plan,B("start"));var prepared=c.Prepare(d,BoundedWorker.MonotonicMilliseconds()+29000);using(var lease=ProtectedAttempt.PinHostBootstrapController(prepared.Path,prepared.Hash))using(var original=ProtectedAttempt.PinNativeBootstrapJournalController(lease,prepared.Fields)){Check(original.NativeDefinitionPlan.Encode()==c.Plan.Encode());Check(prepared.End-prepared.Origin<=25000&&prepared.End<=c.Plan.Deadline);Check(prepared.Fields[2]==c.Plan.Origin.ToString()&&prepared.Fields[3]==c.Plan.Deadline.ToString());Check(!File.Exists(Path.Combine(prepared.Root,"admit")));Refuse(()=>File.Move(prepared.Path,prepared.Path+".old"));Refuse(()=>File.WriteAllText(prepared.Image,"replacement"));}}});
  Test("changed dependency refuses before bootstrap worker creation",()=>{using(var c=new Case()){var d=c.Bootstrap();d["nodeSha256"]=H('e');int before=Directory.GetDirectories(c.Workers).Length;Refuse(()=>c.Prepare(d,BoundedWorker.MonotonicMilliseconds()+29000));Check(Directory.GetDirectories(c.Workers).Length==before);}});
  Test("short command window refuses without renewing original deadline",()=>{using(var c=new Case()){var d=c.Bootstrap();int before=Directory.GetDirectories(c.Workers).Length;Refuse(()=>c.Prepare(d,BoundedWorker.MonotonicMilliseconds()+3000));Check(Directory.GetDirectories(c.Workers).Length==before);}});
  Test("only exact original running allocation receives the nineteen GiB resident credit",()=>{using(var c=new Case()){string guid="12345678-1234-1234-1234-123456789abc";var v=D("Name",guid,"ElementName",c.Plan.Name,"EnabledState",(ushort)2);var m=D("SystemName",guid,"BlockSize",1048576UL,"NumberOfBlocks",19456UL);var setting=D("VirtualSystemIdentifier",guid,"VirtualSystemType","Microsoft:Hyper-V:System:Realized","Notes",new[]{c.Plan.Note});Check(NativeBootstrapAllocation.Fields(c.Plan,guid,v,m,setting)==19L*1073741824);v["EnabledState"]=(ushort)3;Refuse(()=>NativeBootstrapAllocation.Fields(c.Plan,guid,v,m,setting));v["EnabledState"]=(ushort)2;m["NumberOfBlocks"]=20480UL;Refuse(()=>NativeBootstrapAllocation.Fields(c.Plan,guid,v,m,setting));m["NumberOfBlocks"]=19456UL;setting["Notes"]=new[]{"foreign"};Refuse(()=>NativeBootstrapAllocation.Fields(c.Plan,guid,v,m,setting));}});
  Test("bootstrap reserves another group while retaining all native floors and commitments",()=>{Check(WindowsStartAdmission.NativeBootstrapRequired==WindowsStartAdmission.NativeRequired+512L*1048576);Check(WindowsStartAdmission.NativeBootstrapRequired-19L*1073741824>18L*1073741824+39388L*1048576+1073741824);});
  Console.WriteLine("TOTAL "+count+" PASS; actual administrator preparation; allocation rows simulated; no SYSTEM task, WMI, TPM, socket or RPC execution");return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
